import React from 'react';
import { useForm, Controller } from 'react-hook-form';
import { TextField, Button, Box, Typography } from '@mui/material';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import dayjs from 'dayjs';

type RegisterMemberRequest = {
  username: string;
  password: string;
  citizenId: string;
  fullName: string;
  email: string;
  phoneNumber: string;
  dateOfBirth: Date | null;
  address: string;
};

const RegisterForm: React.FC = () => {
  const {
    control,
    handleSubmit,
    formState: { errors },
  } = useForm<RegisterMemberRequest>({
    defaultValues: {
      username: '',
      password: '',
      citizenId: '',
      fullName: '',
      email: '',
      phoneNumber: '',
      dateOfBirth: null,
      address: '',
    },
  });

  const onSubmit = (data: RegisterMemberRequest) => {
    console.log('Form Data:', data);
    // TODO: call API register
  };

  return (
    <Box
      sx={{
        maxWidth: 400,
        mx: 'auto',
        p: 2,
        display: 'flex',
        flexDirection: 'column',
        gap: 2,
      }}
    >
      <Typography variant="h5" textAlign="center">
        Register
      </Typography>

      {/* Username */}
      <Controller
        name="username"
        control={control}
        rules={{ required: 'Username is required' }}
        render={({ field }) => (
          <TextField
            {...field}
            label="Username"
            error={!!errors.username}
            helperText={errors.username?.message}
            fullWidth
          />
        )}
      />

      {/* Password */}
      <Controller
        name="password"
        control={control}
        rules={{ required: 'Password is required', minLength: { value: 6, message: 'Min 6 characters' } }}
        render={({ field }) => (
          <TextField
            {...field}
            label="Password"
            type="password"
            error={!!errors.password}
            helperText={errors.password?.message}
            fullWidth
          />
        )}
      />

      {/* Citizen ID */}
      <Controller
        name="citizenId"
        control={control}
        rules={{ required: 'Citizen ID is required', minLength: { value: 13, message: 'Must be 13 digits' } }}
        render={({ field }) => (
          <TextField
            {...field}
            label="Citizen ID"
            error={!!errors.citizenId}
            helperText={errors.citizenId?.message}
            fullWidth
          />
        )}
      />

      {/* Full Name */}
      <Controller
        name="fullName"
        control={control}
        rules={{ required: 'Full name is required' }}
        render={({ field }) => (
          <TextField
            {...field}
            label="Full Name"
            error={!!errors.fullName}
            helperText={errors.fullName?.message}
            fullWidth
          />
        )}
      />

      {/* Email */}
      <Controller
        name="email"
        control={control}
        rules={{
          required: 'Email is required',
          pattern: { value: /^[^\s@]+@[^\s@]+\.[^\s@]+$/, message: 'Invalid email format' },
        }}
        render={({ field }) => (
          <TextField
            {...field}
            label="Email"
            error={!!errors.email}
            helperText={errors.email?.message}
            fullWidth
          />
        )}
      />

      {/* Phone Number */}
      <Controller
        name="phoneNumber"
        control={control}
        rules={{ required: 'Phone number is required' }}
        render={({ field }) => (
          <TextField
            {...field}
            label="Phone Number"
            error={!!errors.phoneNumber}
            helperText={errors.phoneNumber?.message}
            fullWidth
          />
        )}
      />

      {/* Date of Birth */}
      <Controller
        name="dateOfBirth"
        control={control}
        rules={{ required: 'Date of birth is required' }}
        render={({ field }) => (
          <TextField
            {...field}
            type='date'
            label="Address"
            error={!!errors.dateOfBirth}
            helperText={errors.dateOfBirth?.message}
            fullWidth
          />
        )}
      />

      {/* Address */}
      <Controller
        name="address"
        control={control}
        rules={{ required: 'Address is required' }}
        render={({ field }) => (
          <TextField
            {...field}
            label="Address"
            multiline
            rows={3}
            error={!!errors.address}
            helperText={errors.address?.message}
            fullWidth
          />
        )}
      />

      <Button variant="contained" color="primary" onClick={handleSubmit(onSubmit)} fullWidth>
        Register
      </Button>
    </Box>
  );
};

export default RegisterForm;
